-- 002_achievements.sql - rounds ledger + achievements (draft, pending design approval)
-- Idempotent writes: every natural key has a unique constraint; re-apply is a no-op.

-- Append-only round ledger. round_uuid generated by the game server at round start.
CREATE TABLE IF NOT EXISTS rounds (
  round_uuid   UUID PRIMARY KEY,                -- idempotency key, server-generated
  room_code    TEXT NOT NULL,
  started_at   TIMESTAMPTZ NOT NULL,
  ended_at     TIMESTAMPTZ NOT NULL,
  duration_s   INT NOT NULL,
  bot_level    TEXT NOT NULL DEFAULT 'normal',  -- locked in lobby, server-side
  humans_count INT NOT NULL,
  winner_id    TEXT REFERENCES players(player_id),
  end_reason   TEXT NOT NULL,                   -- deposit | last_standing | abandoned
  eligible     BOOLEAN NOT NULL DEFAULT false,  -- counts toward challenges?
  ineligible_reason TEXT,                       -- too_short | too_few_humans | repeated_pattern | ...
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Per-player round facts, recorded by the server (never client claims).
CREATE TABLE IF NOT EXISTS round_players (
  round_uuid  UUID NOT NULL REFERENCES rounds(round_uuid),
  player_id   TEXT NOT NULL REFERENCES players(player_id),
  result      TEXT NOT NULL,                    -- win | loss
  powers_used INT NOT NULL DEFAULT 0,           -- from server event log
  deposits    INT NOT NULL DEFAULT 0,
  searches    INT NOT NULL DEFAULT 0,
  PRIMARY KEY (round_uuid, player_id)           -- idempotent: one row per player per round
);
CREATE INDEX IF NOT EXISTS idx_rp_player ON round_players(player_id);

-- Achievement definitions. Conditions are evaluated in server code; this stores metadata.
CREATE TABLE IF NOT EXISTS achievements (
  ach_id    TEXT PRIMARY KEY,                   -- wins_50 | hard_bot_20 | no_power_5_streak | streak_7 | ...
  name_ar   TEXT NOT NULL,
  desc_ar   TEXT NOT NULL,
  category  TEXT NOT NULL,                      -- wins | challenge | streak
  target    BIGINT NOT NULL,
  rarity    TEXT NOT NULL DEFAULT 'common'      -- common | rare | legendary
);

-- Per-player progress + unlock date (the "date each rare achievement was earned").
CREATE TABLE IF NOT EXISTS player_achievements (
  player_id   TEXT NOT NULL REFERENCES players(player_id),
  ach_id      TEXT NOT NULL REFERENCES achievements(ach_id),
  progress    BIGINT NOT NULL DEFAULT 0,
  unlocked_at TIMESTAMPTZ,                      -- NULL = still locked
  PRIMARY KEY (player_id, ach_id)
  -- unlock is UPDATE ... WHERE unlocked_at IS NULL: first writer wins, retry is a no-op
);

-- IMMUTABLE audit log. App role gets SELECT+INSERT only (grants below).
CREATE TABLE IF NOT EXISTS achievement_events (
  id          BIGSERIAL PRIMARY KEY,
  player_id   TEXT NOT NULL REFERENCES players(player_id),
  ach_id      TEXT NOT NULL REFERENCES achievements(ach_id),
  unlocked_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  round_uuid  UUID REFERENCES rounds(round_uuid),
  detail      JSONB NOT NULL DEFAULT '{}'
);
-- one unlock event per achievement per player (one-time achievements)
CREATE UNIQUE INDEX IF NOT EXISTS uq_ae_once ON achievement_events(player_id, ach_id);

-- Restricted application role: the game server connects as app_writer, not the owner.
-- (Role creation runs once by the owner; migrations apply grants idempotently.)
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_writer') THEN
    CREATE ROLE app_writer NOLOGIN;
  END IF;
END $$;
GRANT SELECT, INSERT, UPDATE ON players, player_devices, player_stats, player_loadout,
      rounds, round_players, achievements, player_achievements TO app_writer;
GRANT SELECT, INSERT ON achievement_events TO app_writer;   -- NO update/delete: immutable
GRANT USAGE ON SEQUENCE achievement_events_id_seq TO app_writer;
